source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && python -c "
import json, os

# Count repos per tier by total file count (not just .py)
repo_dir = '/root/autodl-tmp/structfuse/full_m1_data/repos'
tiers = {'small': 0, 'medium': 0, 'large': 0, 'xlarge': 0}
tier_repos = {'small': [], 'medium': [], 'large': [], 'xlarge': []}
for d in sorted(os.listdir(repo_dir)):
    full = os.path.join(repo_dir, d)
    if not os.path.isdir(full) or d.endswith('_codeql_db'):
        continue
    total = sum(len(files) for _, _, files in os.walk(full))
    if total < 50:
        tiers['small'] += 1
        tier_repos['small'].append((d, total))
    elif total < 200:
        tiers['medium'] += 1
        tier_repos['medium'].append((d, total))
    elif total < 500:
        tiers['large'] += 1
        tier_repos['large'].append((d, total))
    else:
        tiers['xlarge'] += 1
        tier_repos['xlarge'].append((d, total))

print('Tier counts (by total files):')
for t in ['small', 'medium', 'large', 'xlarge']:
    print(f'  {t}: {tiers[t]} repos')
print(f'  Total: {sum(tiers.values())}')
print()
print('Small repos:', tier_repos['small'])
"

